const archiveUiKeys = ['archiveRetentionHint', 'deepDreamLabel', 'dreamScore', 'deepDreamThresholdDescription'] as const;
const archiveUi: Record<Language, Values<typeof archiveUiKeys>> = {
  zh: ['普通梦境保留 30 天，最多 100 份，超限时按创建时间删除最旧记录。深层梦境不自动清理，仍可手动删除。', '深层梦境', '引用分数', '分数超过此值才转入深层梦境；默认 3，即第 4 次有效引用后晋升。提高阈值不会使已有深层梦境降级。'],
  'zh-Hant': ['普通夢境保留 30 天，最多 100 份，超限時依建立時間刪除最舊記錄。深層夢境不自動清理，仍可手動刪除。', '深層夢境', '引用分數', '分數超過此值才轉入深層夢境；預設 3，即第 4 次有效引用後晉升。提高門檻不會使已有深層夢境降級。'],
  en: ['Ordinary dreams are kept for 30 days, up to 100 records; the oldest by creation time are removed first. Deep dreams are exempt from automatic cleanup and can still be deleted manually.', 'Deep dream', 'Reference score', 'A score above this value promotes a dream. The default of 3 means promotion after the fourth valid reference. Raising the threshold does not demote existing deep dreams.'],
  ja: ['通常の夢は 30 日間、最大 100 件保存し、上限を超えると作成日時が古いものから削除します。深層夢は自動削除の対象外ですが、手動で削除できます。', '深層夢', '参照スコア', 'スコアがこの値を超えると深層夢になります。初期値 3 では、有効な参照が 4 回に達すると移行します。しきい値を上げても既存の深層夢は降格しません。'],
  ko: ['일반 꿈은 30일 동안 최대 100개까지 보관하며, 한도를 넘으면 생성 시간이 가장 오래된 기록부터 삭제합니다. 깊은 꿈은 자동 정리 대상에서 제외되며 수동으로 삭제할 수 있습니다.', '깊은 꿈', '인용 점수', '점수가 이 값을 초과하면 깊은 꿈으로 전환됩니다. 기본값 3에서는 네 번째 유효한 인용 후 전환됩니다. 기준을 높여도 기존 깊은 꿈은 일반 꿈으로 돌아가지 않습니다.'],
  'es-419': ['Los sueños normales se conservan 30 días, hasta 100 registros; se eliminan primero los más antiguos por fecha de creación. Los sueños profundos no se eliminan automáticamente, pero se pueden borrar manualmente.', 'Sueño profundo', 'Puntos por referencias', 'Una puntuación superior a este valor convierte el sueño en profundo. El valor predeterminado de 3 exige una cuarta referencia válida. Aumentar el umbral no revierte los sueños profundos existentes.'],
  fr: ['Les rêves ordinaires sont conservés 30 jours, dans la limite de 100 ; les plus anciens par date de création sont supprimés en premier. Les rêves profonds sont exclus du nettoyage automatique et restent supprimables manuellement.', 'Rêve profond', 'Score de références', 'Un score supérieur à cette valeur fait passer le rêve en rêve profond. La valeur par défaut de 3 exige une quatrième référence valide. Augmenter le seuil ne rétrograde pas les rêves profonds existants.'],
  de: ['Normale Träume bleiben 30 Tage erhalten, höchstens 100 Einträge; die ältesten nach Erstellungszeit werden zuerst gelöscht. Tiefe Träume sind von der automatischen Bereinigung ausgenommen und können weiterhin manuell gelöscht werden.', 'Tiefer Traum', 'Referenzpunkte', 'Ein Punktestand über diesem Wert macht einen Traum zu einem tiefen Traum. Beim Standardwert 3 geschieht dies nach dem vierten gültigen Bezug. Ein höherer Schwellenwert stuft bestehende tiefe Träume nicht zurück.'],
  'pt-BR': ['Sonhos comuns são mantidos por 30 dias, até 100 registros; os mais antigos pela data de criação são removidos primeiro. Sonhos profundos ficam fora da limpeza automática e ainda podem ser excluídos manualmente.', 'Sonho profundo', 'Pontos por referências', 'Uma pontuação acima deste valor torna o sonho profundo. O padrão 3 exige a quarta referência válida. Aumentar o limite não rebaixa sonhos profundos existentes.'],
  it: ['I sogni ordinari vengono conservati per 30 giorni, fino a 100 voci; i più vecchi per data di creazione vengono rimossi per primi. I sogni profondi sono esclusi dalla pulizia automatica e possono essere eliminati manualmente.', 'Sogno profondo', 'Punti di riferimento', 'Un punteggio superiore a questo valore rende il sogno profondo. Il valore predefinito 3 richiede il quarto riferimento valido. Aumentare la soglia non declassa i sogni profondi esistenti.'],
  ru: ['Обычные сновидения хранятся 30 дней, не более 100 записей; сначала удаляются самые старые по времени создания. Глубокие сновидения не удаляются автоматически, но их можно удалить вручную.', 'Глубокое сновидение', 'Баллы за упоминания', 'Сновидение становится глубоким, когда баллы превышают это значение. При стандартном значении 3 нужно четвёртое подтверждённое упоминание. Повышение порога не понижает уже глубокие сновидения.'],
};

